-- Flyway baseline V1
-- Clothing shopping app schema (all phases). utf8mb4 / InnoDB.
-- Primary keys are CHAR(36) UUIDs generated by the application (UUID.randomUUID()).
-- Money is stored as BIGINT minor units (VND has no subunit).
-- Timestamps are DATETIME(6) UTC, managed by Spring Data JPA auditing.

CREATE TABLE users (
    id              CHAR(36) NOT NULL,
    email           VARCHAR(255) NOT NULL,
    password_hash   VARCHAR(100) NOT NULL,
    first_name      VARCHAR(100) NOT NULL,
    last_name       VARCHAR(100) NOT NULL,
    phone           VARCHAR(30),
    role            ENUM('CUSTOMER','ADMIN') NOT NULL,
    status          ENUM('ACTIVE','LOCKED','DISABLED') NOT NULL,
    created_at      DATETIME(6) NOT NULL,
    updated_at      DATETIME(6) NOT NULL,
    CONSTRAINT pk_users PRIMARY KEY (id),
    CONSTRAINT uk_users_email UNIQUE (email)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE refresh_tokens (
    id              CHAR(36) NOT NULL,
    user_id         CHAR(36) NOT NULL,
    token_hash      CHAR(64) NOT NULL,
    expires_at      DATETIME(6) NOT NULL,
    revoked_at      DATETIME(6),
    replaced_by_id  CHAR(36),
    created_at      DATETIME(6) NOT NULL,
    updated_at      DATETIME(6) NOT NULL,
    CONSTRAINT pk_refresh_tokens PRIMARY KEY (id),
    CONSTRAINT fk_refresh_tokens_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    CONSTRAINT uk_refresh_tokens_token_hash UNIQUE (token_hash)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE addresses (
    id                  CHAR(36) NOT NULL,
    user_id             CHAR(36) NOT NULL,
    recipient_name      VARCHAR(100) NOT NULL,
    phone               VARCHAR(30),
    address_line1       VARCHAR(255) NOT NULL,
    address_line2       VARCHAR(255),
    ward                VARCHAR(100),
    district            VARCHAR(100),
    city_or_province    VARCHAR(100) NOT NULL,
    postal_code         VARCHAR(20),
    is_default          BOOLEAN NOT NULL DEFAULT FALSE,
    -- VIRTUAL (not STORED): MySQL forbids ON DELETE CASCADE on the base column
    -- of a stored generated column. The unique index still enforces one default
    -- address per user while allowing the user FK to cascade.
    default_owner       VARCHAR(36) GENERATED ALWAYS AS (IF(is_default, user_id, NULL)) VIRTUAL,
    created_at          DATETIME(6) NOT NULL,
    updated_at          DATETIME(6) NOT NULL,
    CONSTRAINT pk_addresses PRIMARY KEY (id),
    CONSTRAINT fk_addresses_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    CONSTRAINT uk_addresses_default_owner UNIQUE (default_owner),
    INDEX idx_addresses_user (user_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE categories (
    id                CHAR(36) NOT NULL,
    name              VARCHAR(200) NOT NULL,
    slug              VARCHAR(200) NOT NULL,
    description       TEXT,
    parent_id         CHAR(36),
    is_active         BOOLEAN NOT NULL DEFAULT TRUE,
    sort_order        INT NOT NULL DEFAULT 0,
    created_at        DATETIME(6) NOT NULL,
    updated_at        DATETIME(6) NOT NULL,
    CONSTRAINT pk_categories PRIMARY KEY (id),
    CONSTRAINT fk_categories_parent FOREIGN KEY (parent_id) REFERENCES categories(id),
    CONSTRAINT uk_categories_slug UNIQUE (slug),
    INDEX idx_categories_parent (parent_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE products (
    id                CHAR(36) NOT NULL,
    name              VARCHAR(200) NOT NULL,
    slug              VARCHAR(200) NOT NULL,
    short_description VARCHAR(500),
    description       TEXT,
    category_id       CHAR(36) NOT NULL,
    base_price        BIGINT NOT NULL,
    currency          CHAR(3) NOT NULL DEFAULT 'VND',
    status            ENUM('DRAFT','ACTIVE','ARCHIVED') NOT NULL,
    material          VARCHAR(200),
    fit               VARCHAR(100),
    care_instructions TEXT,
    featured          BOOLEAN NOT NULL DEFAULT FALSE,
    created_at        DATETIME(6) NOT NULL,
    updated_at        DATETIME(6) NOT NULL,
    CONSTRAINT pk_products PRIMARY KEY (id),
    CONSTRAINT fk_products_category FOREIGN KEY (category_id) REFERENCES categories(id),
    CONSTRAINT uk_products_slug UNIQUE (slug),
    INDEX idx_products_status_category (status, category_id),
    INDEX idx_products_status_created (status, created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE product_images (
    id            CHAR(36) NOT NULL,
    product_id    CHAR(36) NOT NULL,
    storage_key   VARCHAR(500) NOT NULL,
    alt_text      VARCHAR(200),
    sort_order    INT NOT NULL DEFAULT 0,
    is_primary    BOOLEAN NOT NULL DEFAULT FALSE,
    created_at    DATETIME(6) NOT NULL,
    updated_at    DATETIME(6) NOT NULL,
    CONSTRAINT pk_product_images PRIMARY KEY (id),
    CONSTRAINT fk_product_images_product FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE,
    INDEX idx_product_images_product_sort (product_id, sort_order)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE product_variants (
    id              CHAR(36) NOT NULL,
    product_id      CHAR(36) NOT NULL,
    sku             VARCHAR(64) NOT NULL,
    size            VARCHAR(32),
    color           VARCHAR(64),
    price_override  BIGINT,
    stock_quantity  INT NOT NULL CHECK (stock_quantity >= 0),
    is_active       BOOLEAN NOT NULL DEFAULT TRUE,
    created_at      DATETIME(6) NOT NULL,
    updated_at      DATETIME(6) NOT NULL,
    CONSTRAINT pk_product_variants PRIMARY KEY (id),
    CONSTRAINT fk_product_variants_product FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE,
    CONSTRAINT uk_product_variants_sku UNIQUE (sku),
    CONSTRAINT uk_product_variants_product_size_color UNIQUE (product_id, size, color),
    INDEX idx_product_variants_product (product_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE carts (
    id          CHAR(36) NOT NULL,
    user_id     CHAR(36) NOT NULL,
    created_at  DATETIME(6) NOT NULL,
    updated_at  DATETIME(6) NOT NULL,
    CONSTRAINT pk_carts PRIMARY KEY (id),
    CONSTRAINT fk_carts_user FOREIGN KEY (user_id) REFERENCES users(id),
    CONSTRAINT uk_carts_user UNIQUE (user_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE cart_items (
    id          CHAR(36) NOT NULL,
    cart_id     CHAR(36) NOT NULL,
    variant_id  CHAR(36) NOT NULL,
    quantity    INT NOT NULL CHECK (quantity > 0),
    created_at  DATETIME(6) NOT NULL,
    updated_at  DATETIME(6) NOT NULL,
    CONSTRAINT pk_cart_items PRIMARY KEY (id),
    CONSTRAINT fk_cart_items_cart FOREIGN KEY (cart_id) REFERENCES carts(id) ON DELETE CASCADE,
    CONSTRAINT fk_cart_items_variant FOREIGN KEY (variant_id) REFERENCES product_variants(id),
    CONSTRAINT uk_cart_items_cart_variant UNIQUE (cart_id, variant_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE orders (
    id                      CHAR(36) NOT NULL,
    order_number            VARCHAR(24) NOT NULL,
    user_id                 CHAR(36) NOT NULL,
    status                  ENUM('PENDING_PAYMENT','CONFIRMED','PROCESSING','SHIPPED','DELIVERED','CANCELLED','RETURN_REQUESTED','RETURNED') NOT NULL,
    payment_status          ENUM('UNPAID','PENDING','PAID','FAILED','REFUNDED') NOT NULL,
    subtotal                BIGINT NOT NULL,
    discount_total          BIGINT NOT NULL DEFAULT 0,
    shipping_total          BIGINT NOT NULL DEFAULT 0,
    grand_total             BIGINT NOT NULL,
    currency                CHAR(3) NOT NULL,
    ship_recipient_name     VARCHAR(100),
    ship_phone              VARCHAR(30),
    ship_address_line1      VARCHAR(255),
    ship_address_line2      VARCHAR(255),
    ship_ward               VARCHAR(100),
    ship_district           VARCHAR(100),
    ship_city_or_province   VARCHAR(100),
    ship_postal_code        VARCHAR(20),
    shipping_method_code    VARCHAR(40),
    shipping_method_name    VARCHAR(120),
    customer_note           VARCHAR(500),
    idempotency_key         VARCHAR(80),
    placed_at               DATETIME(6),
    created_at              DATETIME(6) NOT NULL,
    updated_at              DATETIME(6) NOT NULL,
    CONSTRAINT pk_orders PRIMARY KEY (id),
    CONSTRAINT fk_orders_user FOREIGN KEY (user_id) REFERENCES users(id),
    CONSTRAINT uk_orders_order_number UNIQUE (order_number),
    CONSTRAINT uk_orders_user_idempotency UNIQUE (user_id, idempotency_key),
    INDEX idx_orders_user_placed (user_id, placed_at DESC),
    INDEX idx_orders_status_placed (status, placed_at DESC)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE order_items (
    id                CHAR(36) NOT NULL,
    order_id          CHAR(36) NOT NULL,
    variant_id        CHAR(36),
    product_name_snapshot VARCHAR(200) NOT NULL,
    sku_snapshot      VARCHAR(64),
    size_snapshot     VARCHAR(32),
    color_snapshot    VARCHAR(64),
    image_url_snapshot VARCHAR(500),
    unit_price        BIGINT NOT NULL,
    quantity          INT NOT NULL,
    line_total        BIGINT NOT NULL,
    created_at        DATETIME(6) NOT NULL,
    updated_at        DATETIME(6) NOT NULL,
    CONSTRAINT pk_order_items PRIMARY KEY (id),
    CONSTRAINT fk_order_items_order FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE CASCADE,
    CONSTRAINT fk_order_items_variant FOREIGN KEY (variant_id) REFERENCES product_variants(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE order_status_history (
    id          CHAR(36) NOT NULL,
    order_id    CHAR(36) NOT NULL,
    from_status ENUM('PENDING_PAYMENT','CONFIRMED','PROCESSING','SHIPPED','DELIVERED','CANCELLED','RETURN_REQUESTED','RETURNED'),
    to_status   ENUM('PENDING_PAYMENT','CONFIRMED','PROCESSING','SHIPPED','DELIVERED','CANCELLED','RETURN_REQUESTED','RETURNED') NOT NULL,
    actor_user_id CHAR(36),
    note        VARCHAR(500),
    created_at  DATETIME(6) NOT NULL,
    updated_at  DATETIME(6) NOT NULL,
    CONSTRAINT pk_order_status_history PRIMARY KEY (id),
    CONSTRAINT fk_order_status_history_order FOREIGN KEY (order_id) REFERENCES orders(id),
    INDEX idx_order_status_history_order (order_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE payments (
    id                    CHAR(36) NOT NULL,
    order_id              CHAR(36) NOT NULL,
    provider              VARCHAR(32) NOT NULL,
    provider_transaction_id VARCHAR(120),
    amount                BIGINT,
    currency              CHAR(3),
    status                ENUM('PENDING','AUTHORIZED','PAID','FAILED','CANCELLED','REFUNDED') NOT NULL,
    created_at            DATETIME(6) NOT NULL,
    updated_at            DATETIME(6) NOT NULL,
    CONSTRAINT pk_payments PRIMARY KEY (id),
    CONSTRAINT fk_payments_order FOREIGN KEY (order_id) REFERENCES orders(id),
    CONSTRAINT uk_payments_provider_tx UNIQUE (provider, provider_transaction_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE payment_events (
    id                CHAR(36) NOT NULL,
    provider          VARCHAR(32) NOT NULL,
    provider_event_id VARCHAR(120) NOT NULL,
    payload_sha256    CHAR(64) NOT NULL,
    processed_at      DATETIME(6),
    created_at        DATETIME(6) NOT NULL,
    updated_at        DATETIME(6) NOT NULL,
    CONSTRAINT pk_payment_events PRIMARY KEY (id),
    CONSTRAINT uk_payment_events_provider_event UNIQUE (provider, provider_event_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE idempotency_records (
    id             CHAR(36) NOT NULL,
    user_id        CHAR(36) NOT NULL,
    idempotency_key VARCHAR(80) NOT NULL,
    request_hash   CHAR(64) NOT NULL,
    status_code    INT NOT NULL,
    response_body  MEDIUMTEXT,
    created_at     DATETIME(6) NOT NULL,
    updated_at     DATETIME(6) NOT NULL,
    CONSTRAINT pk_idempotency_records PRIMARY KEY (id),
    CONSTRAINT uk_idempotency_records_user_key UNIQUE (user_id, idempotency_key),
    INDEX idx_idempotency_records_created (created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Phase-later tables (P1): created in V1 to avoid schema churn; no API exposes them until Phase 7.
CREATE TABLE wishlists (
    id        CHAR(36) NOT NULL,
    user_id   CHAR(36) NOT NULL,
    created_at DATETIME(6) NOT NULL,
    updated_at DATETIME(6) NOT NULL,
    CONSTRAINT pk_wishlists PRIMARY KEY (id),
    CONSTRAINT fk_wishlists_user FOREIGN KEY (user_id) REFERENCES users(id),
    CONSTRAINT uk_wishlists_user UNIQUE (user_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE wishlist_items (
    id          CHAR(36) NOT NULL,
    wishlist_id CHAR(36) NOT NULL,
    variant_id  CHAR(36) NOT NULL,
    created_at  DATETIME(6) NOT NULL,
    updated_at  DATETIME(6) NOT NULL,
    CONSTRAINT pk_wishlist_items PRIMARY KEY (id),
    CONSTRAINT fk_wishlist_items_wishlist FOREIGN KEY (wishlist_id) REFERENCES wishlists(id) ON DELETE CASCADE,
    CONSTRAINT fk_wishlist_items_variant FOREIGN KEY (variant_id) REFERENCES product_variants(id),
    CONSTRAINT uk_wishlist_items_wishlist_variant UNIQUE (wishlist_id, variant_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE promotions (
    id              CHAR(36) NOT NULL,
    code            VARCHAR(50) NOT NULL,
    name            VARCHAR(200),
    description     TEXT,
    type            ENUM('PERCENT','FIXED') NOT NULL,
    value           BIGINT NOT NULL,
    min_order       BIGINT NOT NULL DEFAULT 0,
    max_discount    BIGINT,
    starts_at       DATETIME(6),
    ends_at         DATETIME(6),
    is_active       BOOLEAN NOT NULL DEFAULT TRUE,
    created_at      DATETIME(6) NOT NULL,
    updated_at      DATETIME(6) NOT NULL,
    CONSTRAINT pk_promotions PRIMARY KEY (id),
    CONSTRAINT uk_promotions_code UNIQUE (code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE reviews (
    id          CHAR(36) NOT NULL,
    product_id  CHAR(36) NOT NULL,
    user_id     CHAR(36) NOT NULL,
    rating      INT NOT NULL CHECK (rating >= 1 AND rating <= 5),
    title       VARCHAR(200),
    comment     TEXT,
    is_verified BOOLEAN NOT NULL DEFAULT FALSE,
    created_at  DATETIME(6) NOT NULL,
    updated_at  DATETIME(6) NOT NULL,
    CONSTRAINT pk_reviews PRIMARY KEY (id),
    CONSTRAINT fk_reviews_product FOREIGN KEY (product_id) REFERENCES products(id),
    CONSTRAINT fk_reviews_user FOREIGN KEY (user_id) REFERENCES users(id),
    INDEX idx_reviews_product (product_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE audit_events (
    id          CHAR(36) NOT NULL,
    actor_user_id CHAR(36),
    action      VARCHAR(100) NOT NULL,
    target_type VARCHAR(100),
    target_id   CHAR(36),
    metadata    JSON,
    created_at  DATETIME(6) NOT NULL,
    updated_at  DATETIME(6) NOT NULL,
    CONSTRAINT pk_audit_events PRIMARY KEY (id),
    INDEX idx_audit_events_actor (actor_user_id),
    INDEX idx_audit_events_created (created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
